def transform(grid):
    n = len(grid)
    m = len(grid[0])

    def rot90(a):
        return [list(row) for row in zip(*a[::-1])]

    def rot180(a):
        return rot90(rot90(a))

    def rot270(a):
        return rot90(rot180(a))

    blocks = [
        [row[:] for row in grid],
        rot90(grid),
        rot270(grid),
        rot180(grid),
    ]
    out = [[0] * (2 * m) for _ in range(2 * n)]
    for bi in range(2):
        for bj in range(2):
            block = blocks[bi * 2 + bj]
            for i in range(n):
                for j in range(m):
                    out[bi * n + i][bj * m + j] = block[i][j]
    return out
